mapper.select:
select ch.*
from video_device_channel ch
join video_platform_gb_channel rel on rel.device_channel_id = ch.channel_id and rel.del_flag = '0'
where ch.del_flag = '0'
and rel.platform_id = #{platformId}
and ch.channel_id = #{channelId}

mapper.update:
update video_device_channel
set sub_count = (select a.cnt from (select count(1) as cnt from video_device_channel
where del_flag = '0' and device_id = #{deviceId} and parent_id = #{channelId}) a)
where del_flag = '0'
and device_id = #{deviceId}
and channel_id = #{channelId}

mapper.select:
select gs.gb_id as channelId, '1' as channelType, gs.name as name, gs.longitude as longitude, gs.latitude as latitude, cat.id as parentId, '1' as registerWay, cat.civil_code as civilCode, 'live' as model, '0' as parental, '0' as secrecy,
ifnull(push.push_ing, 0) ifnull(push.status, ifnull(proxy.status, 0)) as status from video_gb_stream gs join video_platform_gb_stream rel on rel.gb_stream_id = gs.gb_id and rel.del_flag = '0' join video_platform_catalog cat on cat.id = rel.catalog_id and cat.platform_id = rel.platform_id and cat.del_flag = '0' left join video_stream_push push on push.app = gs.app and push.stream = gs.stream and push.del_flag = '0' left join video_stream_proxy proxy on proxy.app = gs.app and proxy.stream = gs.stream and proxy.del_flag = '0' where gs.del_flag = '0' and rel.platform_id = #{serverGbId}
and gs.gb_id = #{gbId}
